-- Migration 0035 (spec 14.28): airports and traffic for every home region (regions step 1 of 3).
--
-- What changes:
--  * 271 new airports: the busiest of the USA, Canada, Europe, the Middle East, China, Africa and South America, and
--    destinations a world there flies to (Mexico and the Caribbean, Japan, Pakistan, Brisbane). Each has its passengers
--    a year, international share, share not changing planes (od_share), business and tourism indices, runway class
--    (from OurAirports runway lengths) and a daily slot cap where congested. Passenger figures are estimates
--    (pax_src G) until checked against the published lists.
--  * The 69 foreign airports already in the game get the same figures and the home region they belong to. Their
--    mass, slot caps and indices do not change; Beijing, Shanghai, Guangzhou and Hong Kong move from region EASIA
--    to CHN (nothing reads EASIA).
--  * airports.home: the home region whose worlds can found airlines and open bases there ('india' for India;
--    null for destination-only airports). airports.seen_in: the regions whose worlds show the airport (its home,
--    or a market to an airport of that region). The app shows a world only the airports seen in its region.
--  * 25,690 new markets between airports outside India, from tools/build_regions.py (doubly constrained gravity,
--    domestic per country and between countries, India's international flows taken off first). India's 6,584
--    markets are not touched: Test World and World 1 see the same demand, airports and routes as before.
--  * markets.zone: the home region when both ends share it ('india' for India's domestic markets). A trigger sets it.
--  * The computer-run airlines' "eight busiest domestic markets" (bot_exit, bot_exit_v1, bot_quarter) are now the
--    eight busiest of the world's own region; for India worlds that is exactly the list they had.
--  * route_study refuses a pair with neither end in the world's region (an India world cannot study Atlanta-Denver).
--  * rebuild_markets clears only markets touching India before rebuilding them, so a rebuild keeps the other regions.
--  * game.world_region(world): the world's region (worlds.rules ->> 'region', India when not set).

alter table public.airports
  add column home text check (home in ('india', 'usa', 'canada', 'europe', 'middle_east', 'china', 'africa', 'south_america')),
  add column od_share numeric check (od_share > 0 and od_share <= 1),   -- share of passengers not changing planes there
  add column seen_in text[] not null default '{}';
alter table public.airports drop constraint airports_check;
alter table public.airports add constraint airports_check
  check ((is_india and pax_m is not null and intl_share is not null) or (not is_india and (mass is not null or pax_m is not null)));
update public.airports set home = 'india', od_share = 1 where is_india;

alter table public.markets add column zone text;   -- the home region when both ends are in it

create or replace function game.market_zone() returns trigger
language plpgsql set search_path = '' as $$
begin
  select case when x.home = y.home then x.home end into new.zone
    from public.airports x, public.airports y where x.iata = new.a and y.iata = new.b;
  return new;
end $$;
create trigger markets_zone before insert or update of a, b on public.markets
  for each row execute function game.market_zone();
update public.markets set zone = 'india'
 where exists (select 1 from public.airports x where x.iata = a and x.is_india)
   and exists (select 1 from public.airports y where y.iata = b and y.is_india);

create or replace function game.world_region(p_world uuid) returns text
language sql stable set search_path = '' as $$
  select coalesce((select nullif(rules ->> 'region', '') from public.worlds where id = p_world), 'india')
$$;

