insert into public.markets (a, b, km, intl, n_biz, n_lei, n_bud, ref_fare)
select f.a, f.b, round(x.km)::int, p.country <> q.country,
       round((f.n * x.sb)::numeric, 1), round((f.n * (1 - x.sb) * x.sl)::numeric, 1),
       round((f.n * (1 - x.sb) * (1 - x.sl))::numeric, 1),
       (round((game.param('ref_fare_fixed') + game.param('ref_fare_per_km') * x.km) / 10) * 10)::int
  from region_flows f
  join public.airports p on p.iata = f.a
  join public.airports q on q.iata = f.b
  cross join lateral (select game.haversine_km(p.lat::float8, p.lon::float8, q.lat::float8, q.lon::float8) as km,
                             0.08 + 0.27 * (p.biz_idx + q.biz_idx)::float8 / 2 as sb,
                             0.30 + 0.45 * greatest(p.tour_idx, q.tour_idx)::float8 as sl) x;
drop table region_flows;

-- which worlds show each airport: its own region's, and those of every region it has a market with
update public.airports ap set seen_in = s.regions
  from (select x, array_agg(distinct r order by r) as regions
          from (select iata as x, home as r from public.airports where home is not null
                union
                select e.x, o.home from (select a as x, b as y from public.markets union all select b, a from public.markets) e
                  join public.airports o on o.iata = e.y where o.home is not null) z
         group by x) s
 where ap.iata = s.x;

revoke all on all functions in schema game from public, anon, authenticated;

-- The eight busiest markets a computer-run airline never closes are its own region's (0035; was: not intl).
CREATE OR REPLACE FUNCTION game.bot_exit(p_world uuid, p_day integer)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r record; v_n int := 0;
begin
  if game.param('bot_plan') = 0 then return game.bot_exit_v1(p_world, p_day); end if;
  for r in
    select rt.id, rt.airline_id
      from public.routes rt join public.airlines al on al.id = rt.airline_id and al.is_ai and al.status = 'active'
     where rt.world_id = p_world and rt.status = 'open' and rt.opened_day <= p_day - game.param('bot_exit_min_days')
       and game.bot_entered(rt.airline_id, rt.origin, rt.dest)
       and coalesce((select sum(z.pax_econ + z.pax_biz)::numeric / nullif(sum(z.seats_econ + z.seats_biz), 0)
                       from public.route_daily z where z.route_id = rt.id and z.game_day > p_day - 28), 0) < game.param('bot_exit_lf')
  loop
    perform game.bot_close(r.airline_id, r.id, p_day);
    v_n := v_n + 1;
  end loop;
  for r in
    select rt.id, rt.airline_id,
           coalesce((select sum(z.revenue_inr - z.var_cost_inr - z.aircraft_cost_inr) from public.route_daily z
                      where z.route_id = rt.id and z.game_day > p_day - 28), 0) as result
      from public.routes rt join public.airlines al on al.id = rt.airline_id and al.is_ai and al.status = 'active'
     where rt.world_id = p_world and rt.status = 'open' and rt.opened_day <= p_day - game.param('bot_drop_min_days')
       and not game.bot_entered(rt.airline_id, rt.origin, rt.dest)
       and (select count(*) from public.route_daily z where z.route_id = rt.id and z.game_day > p_day - 28) >= 21
       and coalesce((select sum(z.pax_econ + z.pax_biz)::numeric / nullif(sum(z.seats_econ + z.seats_biz), 0)
                       from public.route_daily z where z.route_id = rt.id and z.game_day > p_day - 28), 0) < game.param('bot_drop_lf')
       and (least(rt.origin, rt.dest), greatest(rt.origin, rt.dest)) not in
           (select m.a, m.b from public.markets m where m.zone = game.world_region(p_world) order by m.n_biz + m.n_lei + m.n_bud desc limit 8)
     order by 3
  loop
    continue when r.result >= 0;
    continue when (select count(*) from public.routes o where o.airline_id = r.airline_id and o.status = 'open') <= game.param('bot_keep_routes');
    perform game.bot_close(r.airline_id, r.id, p_day);
    v_n := v_n + 1;
  end loop;
  return v_n;
end $function$;

CREATE OR REPLACE FUNCTION game.bot_exit_v1(p_world uuid, p_day integer)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r record; x record; v_n int := 0; rw public.worlds%rowtype;
begin
  select * into rw from public.worlds where id = p_world;
  for r in
    select rt.id, rt.airline_id, rt.origin, rt.dest, al.name
      from public.routes rt join public.airlines al on al.id = rt.airline_id and al.is_ai and al.status = 'active'
     where rt.world_id = p_world and rt.status = 'open' and rt.opened_day <= p_day - game.param('bot_exit_min_days')
       and game.bot_entered(rt.airline_id, rt.origin, rt.dest)
       and coalesce((select sum(z.pax_econ + z.pax_biz)::numeric / nullif(sum(z.seats_econ + z.seats_biz), 0)
                       from public.route_daily z where z.route_id = rt.id and z.game_day > p_day - 28), 0) < game.param('bot_exit_lf')
  loop
    for x in select aircraft_id from public.rotations where route_id = r.id loop
      perform public.return_aircraft(r.airline_id, x.aircraft_id);
    end loop;
    perform public.close_route(r.airline_id, r.id);
    insert into public.news (world_id, game_day, airline_id, kind, body, private)
    values (p_world, p_day, r.airline_id, 'route',
            format('%s stops flying %s to %s.', r.name, (select city from public.airports where iata = r.origin),
                   (select city from public.airports where iata = r.dest)), false);
    v_n := v_n + 1;
  end loop;

  -- Migration 0016: a starting route that does not pay its way. Over the last 28 days its fares and extras did not cover its
  -- flying costs and its aircraft's rent, and it was less than bot_drop_lf full, after it has flown bot_drop_min_days (and on at
  -- least 21 of those 28 days, so a fleet grounded for weeks never counts as a thin route). Never one of the eight busiest domestic
  -- markets, and never below bot_keep_routes routes. Its aircraft leave the world (lessors place them elsewhere), so this
  -- never adds aircraft for players (principle 6). Worst route first.
  for r in
    select rt.id, rt.airline_id, rt.origin, rt.dest, al.name,
           coalesce((select sum(z.revenue_inr - z.var_cost_inr) from public.route_daily z
                      where z.route_id = rt.id and z.game_day > p_day - 28), 0)
           - 28 * coalesce((select sum(case tm.holding when 'lease' then tm.lease_usd_month * rw.fx_inr_usd / 30.33
                                                       when 'owned' then tm.price_usd * rw.fx_inr_usd * game.param('depreciation_year') / 364
                                                       else 0 end)
                              from public.rotations ro join public.aircraft_terms tm on tm.aircraft_id = ro.aircraft_id
                             where ro.route_id = rt.id), 0) as result
      from public.routes rt join public.airlines al on al.id = rt.airline_id and al.is_ai and al.status = 'active'
     where rt.world_id = p_world and rt.status = 'open' and rt.opened_day <= p_day - game.param('bot_drop_min_days')
       and not game.bot_entered(rt.airline_id, rt.origin, rt.dest)
       and (select count(*) from public.route_daily z where z.route_id = rt.id and z.game_day > p_day - 28) >= 21
       and coalesce((select sum(z.pax_econ + z.pax_biz)::numeric / nullif(sum(z.seats_econ + z.seats_biz), 0)
                       from public.route_daily z where z.route_id = rt.id and z.game_day > p_day - 28), 0) < game.param('bot_drop_lf')
       and (least(rt.origin, rt.dest), greatest(rt.origin, rt.dest)) not in
           (select m.a, m.b from public.markets m where m.zone = game.world_region(p_world) order by m.n_biz + m.n_lei + m.n_bud desc limit 8)
     order by 6
  loop
    continue when r.result >= 0;
    continue when (select count(*) from public.routes o where o.airline_id = r.airline_id and o.status = 'open') <= game.param('bot_keep_routes');
    for x in select aircraft_id from public.rotations where route_id = r.id loop
      perform public.return_aircraft(r.airline_id, x.aircraft_id);
      update public.aircraft set status = 'returned' where id = x.aircraft_id and status = 'pool';
    end loop;
    perform public.close_route(r.airline_id, r.id);
    insert into public.news (world_id, game_day, airline_id, kind, body, private)
    values (p_world, p_day, r.airline_id, 'route',
            format('%s stops flying %s to %s.', r.name, (select city from public.airports where iata = r.origin),
                   (select city from public.airports where iata = r.dest)), false);
    v_n := v_n + 1;
  end loop;
  return v_n;
end $function$;

CREATE OR REPLACE FUNCTION game.bot_quarter(p_world uuid, p_day integer)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  al record; r record; v_n int := 0; v_min int := game.param('bot_min_weekly')::int;
begin
  if game.param('bot_plan') = 0 then return game.bot_quarter_v1(p_world, p_day); end if;
  v_n := game.bot_exit(p_world, p_day);
  v_n := v_n + game.bot_enter(p_world, p_day);
  drop table if exists pg_temp._bot_grow;
  create temp table _bot_grow (route_id uuid primary key) on commit drop;
  for al in select a.id from public.airlines a where a.world_id = p_world and a.is_ai and a.status = 'active' order by a.code loop
    drop table if exists pg_temp._bst;
    create temp table _bst on commit drop as
    select p.route_id, p.trips,
           ((sum(d.revenue_inr) - sum(d.var_cost_inr + d.aircraft_cost_inr)) / nullif(sum(d.revenue_inr), 0))::float8 as margin,
           (sum(d.pax_econ + d.pax_biz)::numeric / nullif(sum(d.seats_econ + d.seats_biz), 0))::float8 as lf,
           count(*) as days
      from game.bot_plan p join public.route_daily d on d.route_id = p.route_id and d.game_day > p_day - 28
     where p.airline_id = al.id and p.since_day <= p_day - game.param('bot_exit_min_days') and p.trips > 0
     group by p.route_id, p.trips;
    -- 0029: concentrate. A route losing more than bot_close_margin, or one a cut would leave below bot_keep_weekly round
    -- trips, closes outright (never one of the eight busiest domestic markets, never below bot_keep_routes routes); its
    -- aircraft go to the routes that earn, or back to the lessors (bot_balance). The rest of the losing routes are cut.
    if game.param('bot_concentrate') >= 1 then
      v_min := game.param('bot_keep_weekly')::int;
      for r in
        select s.route_id from pg_temp._bst s join public.routes rt on rt.id = s.route_id and rt.status = 'open'
         where s.days >= 21 and s.margin < game.param('bot_cut_margin')
           and (s.margin < game.param('bot_close_margin') or round(s.trips * (1 - game.param('bot_cut_share'))) < v_min)
           and (least(rt.origin, rt.dest), greatest(rt.origin, rt.dest)) not in
               (select m.a, m.b from public.markets m where m.zone = game.world_region(p_world) order by m.n_biz + m.n_lei + m.n_bud desc limit 8)
         order by s.margin
      loop
        exit when (select count(*) from public.routes o where o.airline_id = al.id and o.status = 'open') <= game.param('bot_keep_routes');
        perform game.bot_close(al.id, r.route_id, p_day);
        v_n := v_n + 1;
      end loop;
    end if;
    update game.bot_plan p set trips = greatest(least(p.trips, v_min), round(p.trips * (1 - game.param('bot_cut_share')))::int)
      from pg_temp._bst s
     where s.route_id = p.route_id and s.days >= 21 and s.margin < game.param('bot_cut_margin');
    insert into pg_temp._bot_grow (route_id)
    select s.route_id from pg_temp._bst s
     where s.days >= 21 and s.margin > game.param('bot_grow_margin') and s.lf > game.param('bot_grow_lf')
    on conflict do nothing;
    update game.bot_plan p set trips = ceil(p.trips * (1 + game.param('bot_grow_share')))::int
      from pg_temp._bot_grow g where g.route_id = p.route_id and p.airline_id = al.id;
    v_n := v_n + game.bot_balance(al.id, p_day, true);
  end loop;
  return v_n;
end $function$;

-- A rebuild clears only the markets touching India: the other regions' markets stay (0035).
CREATE OR REPLACE FUNCTION game.rebuild_markets()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_cap float8 := game.param('capture_ref');
  v_ff  float8 := game.param('ref_fare_fixed');
  v_fk  float8 := game.param('ref_fare_per_km');
  v_n   int;
begin
  insert into game.market_balance (iata, f)
  select iata, 1.0 from public.airports where is_india
  on conflict (iata) do update set f = 1.0;

  insert into game.market_weights (a, b, km, w)
  select p.iata, q.iata,
         game.haversine_km(p.lat::float8, p.lon::float8, q.lat::float8, q.lon::float8),
         game.air_share(game.haversine_km(p.lat::float8, p.lon::float8, q.lat::float8, q.lon::float8))
  from public.airports p join public.airports q on p.iata <> q.iata and p.is_india and q.is_india
  on conflict (a, b) do update set km = excluded.km, w = excluded.w;

  -- balance airports that are open from day 0
  for i in 1..150 loop
    update game.market_balance x set f = x.f * sqrt(s.dom / s.tot)
    from (select p.iata, (p.pax_m * (1 - p.intl_share))::float8 as dom,
                 sum(bp.f * bq.f * (p.pax_m * (1 - p.intl_share))::float8
                     * (q.pax_m * (1 - q.intl_share))::float8 * w.w) as tot
          from public.airports p
          join game.market_balance bp on bp.iata = p.iata
          join game.market_weights w on w.a = p.iata
          join public.airports q on q.iata = w.b
          join game.market_balance bq on bq.iata = q.iata
          where p.is_india and q.is_india and p.opens_day = 0 and q.opens_day = 0
          group by p.iata, p.pax_m, p.intl_share) s
    where x.iata = s.iata;
  end loop;
  -- airports that open later borrow the factor of their city's established airport
  update game.market_balance x set f = s.f
  from public.airports p join game.market_balance s on s.iata = p.sibling
  where x.iata = p.iata and p.opens_day > 0;

  update public.markets mk set n_biz = 0, n_lei = 0, n_bud = 0 where n_biz + n_lei + n_bud > 0
     and exists (select 1 from public.airports x where x.iata in (mk.a, mk.b) and x.is_india);

  insert into public.markets (a, b, km, intl, n_biz, n_lei, n_bud, ref_fare)
  select a, b, round(km)::int, false,
         round((n * sb)::numeric, 1), round((n * (1 - sb) * sl)::numeric, 1), round((n * (1 - sb) * (1 - sl))::numeric, 1),
         (round((v_ff + v_fk * km) / 10) * 10)::int
  from (select p.iata as a, q.iata as b, w.km,
               bp.f * bq.f * (p.pax_m * (1 - p.intl_share))::float8 * (q.pax_m * (1 - q.intl_share))::float8
                 * w.w * 1e6 / 2 / 365 / v_cap as n,
               0.08 + 0.27 * (p.biz_idx + q.biz_idx)::float8 / 2 as sb,
               0.30 + 0.45 * greatest(p.tour_idx, q.tour_idx)::float8 as sl
        from public.airports p
        join game.market_balance bp on bp.iata = p.iata
        join game.market_weights w on w.a = p.iata
        join public.airports q on q.iata = w.b
        join game.market_balance bq on bq.iata = q.iata
        where p.is_india and q.is_india and p.iata < q.iata) x
  on conflict (a, b) do update set km = excluded.km, intl = excluded.intl, n_biz = excluded.n_biz,
    n_lei = excluded.n_lei, n_bud = excluded.n_bud, ref_fare = excluded.ref_fare;

  insert into public.markets (a, b, km, intl, n_biz, n_lei, n_bud, ref_fare)
  select least(ia, fa), greatest(ia, fa), round(km)::int, true,
         round((n * sb)::numeric, 1), round((n * (1 - sb) * sl)::numeric, 1), round((n * (1 - sb) * (1 - sl))::numeric, 1),
         (round((v_ff + v_fk * km) / 10) * 10)::int
  from (select i.iata as ia, f.iata as fa,
               game.haversine_km(i.lat::float8, i.lon::float8, f.lat::float8, f.lon::float8) as km,
               (i.pax_m * i.intl_share)::float8 * (f.mass * coalesce(af.mult, 1))::float8 / tot.w
                 * 1e6 / 2 / 365 / v_cap as n,
               0.08 + 0.27 * (i.biz_idx + f.biz_idx)::float8 / 2 as sb,
               0.30 + 0.45 * greatest(i.tour_idx, f.tour_idx)::float8 as sl
        from public.airports i
        join public.airports f on not f.is_india
        left join public.intl_affinity af on af.india_region = i.region and af.foreign_region = f.region
        join (select i2.iata, sum(f2.mass * coalesce(af2.mult, 1))::float8 as w
              from public.airports i2
              join public.airports f2 on not f2.is_india
              left join public.intl_affinity af2 on af2.india_region = i2.region and af2.foreign_region = f2.region
              where i2.is_india
              group by i2.iata) tot on tot.iata = i.iata
        where i.is_india and i.pax_m * i.intl_share > 0) x
  where n >= 1
  on conflict (a, b) do update set km = excluded.km, intl = excluded.intl, n_biz = excluded.n_biz,
    n_lei = excluded.n_lei, n_bud = excluded.n_bud, ref_fare = excluded.ref_fare;

  select count(*) into v_n from public.markets;
  return v_n;
end $function$;

-- A study needs one end in the world's region (0035).
CREATE OR REPLACE FUNCTION public.route_study(p_airline uuid, p_a text, p_b text, p_depth text DEFAULT 'quick'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  rw public.worlds%rowtype; m public.markets%rowtype; s public.route_studies%rowtype;
  v_day int; v_w numeric; v_cost numeric; v_e numeric;
  v_fly numeric; v_turn numeric; v_seats numeric; v_days int; v_grow numeric; v_untap numeric; v_block numeric;
  v_sb numeric; v_sl numeric; v_su numeric;
begin
  rw := game.actor(p_airline); v_day := rw.game_day + 1;
  if p_depth is null or p_depth not in ('quick', 'full') then raise exception 'A study is quick or full'; end if;
  select * into m from public.markets where a = least(upper(p_a), upper(p_b)) and b = greatest(upper(p_a), upper(p_b));
  if not found or not exists (select 1 from public.airports x where x.iata in (m.a, m.b) and x.home = game.world_region(rw.id)) then
    raise exception 'There is no market between % and %', p_a, p_b;
  end if;
  v_cost := game.param('study_' || p_depth || '_inr');
  v_w := game.param('study_' || p_depth || '_width');
  perform game.book(p_airline, v_day, -v_cost, 'study',
                    format('%s route study, %s-%s', initcap(p_depth), m.a, m.b), -v_cost);

  select sum(d.pax_econ + d.pax_biz), sum(d.spill), sum(d.seats_econ + d.seats_biz), count(distinct d.game_day)
    into v_fly, v_turn, v_seats, v_days
    from public.routes r join public.route_daily d on d.route_id = r.id and d.game_day > rw.game_day - 28
   where r.world_id = rw.id and least(r.origin, r.dest) = m.a and greatest(r.origin, r.dest) = m.b;

  s.airline_id := p_airline; s.world_id := rw.id; s.a := m.a; s.b := m.b; s.game_day := v_day; s.depth := p_depth;
  select count(distinct r.airline_id) into s.carriers from public.routes r
   where r.world_id = rw.id and r.status = 'open' and least(r.origin, r.dest) = m.a and greatest(r.origin, r.dest) = m.b
     and exists (select 1 from public.rotations ro where ro.route_id = r.id);

  -- each figure gets its own error, then the range around it
  if coalesce(v_fly, 0) > 0 then
    v_e := greatest(0.3, 1 + v_w / 2 * game.rand_normal());
    s.flying_lo := round(v_fly / v_days / 2 * v_e * (1 - v_w)); s.flying_hi := round(v_fly / v_days / 2 * v_e * (1 + v_w));
    v_e := greatest(0.3, 1 + v_w / 2 * game.rand_normal());
    s.turned_lo := round(v_turn / v_days / 2 * v_e * (1 - v_w)); s.turned_hi := round(v_turn / v_days / 2 * v_e * (1 + v_w));
    v_e := greatest(0.3, 1 + v_w / 4 * game.rand_normal());
    s.lf_lo := round(least(1, v_fly / v_seats * v_e * (1 - v_w / 2)), 3); s.lf_hi := round(least(1, v_fly / v_seats * v_e * (1 + v_w / 2)), 3);
  else
    -- one airline, two round trips a day, reference fare, standard A320neo cabin: P(fly) = e^U / (1 + e^U) per segment
    v_grow := power(1 + game.wparam(rw.id, case when m.intl then 'growth_year_intl' else 'growth_year' end), (v_day - 1) / 364.0) * rw.demand_scale;
    v_block := m.km / 830.0 + 0.7;
    select f.biz, f.lei, f.bud into v_sb, v_sl, v_su from public.season_factors f
     where f.month = ((game.param('season_start_month')::int - 1 + (((v_day - 1) % 364) * 12) / 364) % 12) + 1;
    select sum(n * exp(u) / (1 + exp(u))) into v_untap from (values
      (m.n_biz * v_sb, game.param('seg_biz_a') - game.param('seg_biz_price') + game.param('seg_biz_freq') * ln(3)
                       + game.param('seg_biz_comfort') * (1 / 6.0) * sqrt(v_block)),
      (m.n_lei * v_sl, game.param('seg_lei_a') - game.param('seg_lei_price') + game.param('seg_lei_freq') * ln(3)
                       + game.param('seg_lei_comfort') * (1 / 6.0) * sqrt(v_block)),
      (m.n_bud * v_su, game.param('seg_bud_a') - game.param('seg_bud_price') + game.param('seg_bud_freq') * ln(3)
                       + game.param('seg_bud_comfort') * (1 / 6.0) * sqrt(v_block))) as x(n, u);
    v_untap := v_untap * v_grow;
    v_e := greatest(0.3, 1 + v_w / 2 * game.rand_normal());
    s.untapped_lo := round(v_untap * v_e * (1 - v_w)); s.untapped_hi := round(v_untap * v_e * (1 + v_w));
  end if;

  if p_depth = 'full' then
    s.biz_share := round(m.n_biz / (m.n_biz + m.n_lei + m.n_bud), 2);
    s.lei_share := round(m.n_lei / (m.n_biz + m.n_lei + m.n_bud), 2);
    s.bud_share := round(1 - s.biz_share - s.lei_share, 2);
    s.next_qtr := round(game.season_mix(v_day + 91, m.n_biz, m.n_lei, m.n_bud) / game.season_mix(v_day, m.n_biz, m.n_lei, m.n_bud)
                        * power(1 + game.wparam(rw.id, case when m.intl then 'growth_year_intl' else 'growth_year' end), 91 / 364.0), 2);
  end if;

  insert into public.route_studies (airline_id, world_id, a, b, game_day, depth, carriers, flying_lo, flying_hi, turned_lo, turned_hi,
                                    lf_lo, lf_hi, untapped_lo, untapped_hi, biz_share, lei_share, bud_share, next_qtr)
  values (s.airline_id, s.world_id, s.a, s.b, s.game_day, s.depth, s.carriers, s.flying_lo, s.flying_hi, s.turned_lo, s.turned_hi,
          s.lf_lo, s.lf_hi, s.untapped_lo, s.untapped_hi, s.biz_share, s.lei_share, s.bud_share, s.next_qtr)
  returning id into s.id;
  return to_jsonb(s);
end $function$;

revoke all on all functions in schema game from public, anon, authenticated;
